package assignment5;
import java.nio.file.*;import java.io.*;import java.sql.*;
public class MigrationDemo{public static void main(String[]x)throws Exception{Path f=Path.of("data","bus_passes.csv");int ok=0,bad=0;try(Connection c=Db.connect()){boolean old=c.getAutoCommit();c.setAutoCommit(false);try(BufferedReader r=Files.newBufferedReader(f);PreparedStatement p=c.prepareStatement("INSERT INTO bus_pass VALUES(?,?,?,?,?)")){String line;while((line=r.readLine())!=null){String[]a=line.split(",",-1);try{if(a.length!=5)throw new IllegalArgumentException("wrong field count");p.setString(1,a[0]);p.setString(2,a[1]);p.setString(3,a[2]);p.setInt(4,Integer.parseInt(a[3]));p.setDouble(5,Double.parseDouble(a[4]));p.addBatch();ok++;}catch(RuntimeException e){bad++;System.out.println("Rejected: "+line+" | "+e.getMessage());}}p.executeBatch();c.commit();}catch(Exception e){c.rollback();throw e;}finally{c.setAutoCommit(old);}}System.out.println("Valid rows="+ok+", invalid rows="+bad);}}
